
import axios from 'axios';
import PostsPageModel from '@/data/models/PostsPageModel';
import PostsDetailsModel from '@/data/models/PostDetailsModel';

class PostsRepository{

    private API_METHODS = {
        API_POSTS_PAGE: "/data/pages/",
        API_POST_DETAILS: "/data/posts/"
    }

    constructor (private baseIUrl: string){
        
    }

    async getPostsPage(page: number): Promise<PostsPageModel>{
        const url = this.baseIUrl + this.API_METHODS.API_POSTS_PAGE + page+'.json'
        const response = await axios.get(url, {method: "get", baseURL: "/"})
        return response.data
    }

    async getPostDetails(id: string): Promise<PostsDetailsModel>{
        const url = this.baseIUrl + this.API_METHODS.API_POST_DETAILS + id + "/" + id +'.json'
        const response = await axios.get(url)
        return response.data
    }

    async getPostMarkdown(id: string): Promise<string>{
        const url = this.baseIUrl + this.API_METHODS.API_POST_DETAILS + id + "/" + id + ".md"
        const response = await axios.get<string>(url, { responseType: 'text' })
        return response.data
    }
}

export default PostsRepository