import { marked, Renderer } from 'marked'

export function resolveAssetUrl(href: string, baseUrl: string): string {
    if (/^(https?:|\/\/|data:|mailto:|#)/i.test(href)) {
        return href
    }
    if (href.startsWith('/')) {
        return href
    }
    const normalized = href.replace(/^\.\//, '')
    return baseUrl + normalized
}

export function renderMarkdown(markdown: string, postBaseUrl: string): string {
    const renderer = new Renderer()

    renderer.link = function ({ href, title, tokens }) {
        const resolvedHref = resolveAssetUrl(href, postBaseUrl)
        const text = this.parser.parseInline(tokens)
        const titleAttr = title ? ` title="${title}"` : ''
        const externalAttrs = /^https?:/i.test(resolvedHref)
            ? ' target="_blank" rel="noopener noreferrer"'
            : ''
        return `<a href="${resolvedHref}"${titleAttr}${externalAttrs}>${text}</a>`
    }

    renderer.image = ({ href, title, text }) => {
        const src = resolveAssetUrl(href, postBaseUrl)
        const titleAttr = title ? ` title="${title}"` : ''
        const alt = text ?? ''
        return `<img src="${src}" alt="${alt}"${titleAttr} />`
    }

    return marked.parse(markdown, { renderer, async: false }) as string
}
