
import { Component, Prop, Vue } from 'vue-property-decorator'
import PostModel from '@/data/models/PostModel'
import PostsService from '@/data/PostsService'

@Component
export default class PostsListItem extends Vue{

    @Prop({required: true}) readonly model!: PostModel

    private coverIndex = 0
    private backgroundUrl: string | null = null

    private get coverMode(): 'right' | 'left' | 'fill' | 'background' | 'none' {
        const value = this.model.cover
        return (value === 'right' || value === 'left' || value === 'fill' || value === 'background') ? value : 'none'
    }

    private get hasCover(): boolean {
        return this.coverMode !== 'none'
    }

    private get backgroundStyle(): Record<string, string> | undefined {
        return this.coverMode === 'background' && this.backgroundUrl
            ? { backgroundImage: `url("${this.backgroundUrl}")` }
            : undefined
    }

    private get coverCandidates(): string[] {
        return new PostsService().getCoverCandidates(this.model.id)
    }

    private get coverUrl(): string | null {
        return this.coverCandidates[this.coverIndex] ?? null
    }

    private onCoverError(): void {
        if (this.coverIndex < this.coverCandidates.length) {
            this.coverIndex++
        }
    }

    mounted(): void {
        if (this.coverMode === 'background') {
            this.probeCoverImage(0)
        }
    }

    private probeCoverImage(index: number): void {
        const candidates = this.coverCandidates
        if (index >= candidates.length) {
            return
        }
        const image = new Image()
        image.onload = () => {
            this.backgroundUrl = candidates[index]
        }
        image.onerror = () => {
            this.probeCoverImage(index + 1)
        }
        image.src = candidates[index]
    }
}
