
import { Component, Vue } from 'vue-property-decorator'
import { AxiosError } from 'axios'
//----------------------------------------------------------
import PostModel from '@/data/models/PostModel'
import PostsService from '@/data/PostsService'
import ErrorModel from '@/data/models/ErrorModel'
import ErrorContainer from '@/components/ErrorContainer.vue'
import PostsListItem from '@/components/PostsListItem.vue'


@Component({
  components: {
    PostsListItem,
    ErrorContainer,

  }
})
export default class BlogView extends Vue{

  private postsService: PostsService = new PostsService()

  private currentPostsPage = 1
  private postsPagesCount = 1
  private posts: Array<PostModel> = []

  currentError: ErrorModel|null = null
  
  created () {
    document.title = "Posts"
    this.currentPostsPage = Number.parseInt(this.$route.params.page)
    if (Number.isNaN(this.currentPostsPage) || this.currentPostsPage<1){
      this.currentPostsPage = 1
    }

    if (this.posts.length==0){
      this.getPosts()
    }
  }

  public getPosts(): void {
    this.currentError = null
    this.postsService.getPosts(this.currentPostsPage).then(
      postsPage =>{
        //console.log(postsPage)
        this.currentPostsPage = postsPage.current
        this.postsPagesCount = postsPage.total
        this.posts = postsPage.posts
    }).catch(error => {
    
        if (error as AxiosError) {
                const responseCode = error.response?.status ?? 0
                console.log("Error received code: "+responseCode)
                if (responseCode == 404) {
                    this.currentError = ErrorModel.pageNotFound()
                } else {
                    this.currentError = ErrorModel.loadPageError(this.getPosts)
                }
        } else {
            this.currentError = ErrorModel.loadPageError(this.getPosts)
        }
    })
  }

  public onPageClicked(page: number): void{
    if (this.currentPostsPage == page)return


    this.$router.push(`/posts/pages/`+page)
    //this.currentPostsPage = page
    //this.getPosts()
  }

}
