const SITE_URL = 'https://vv-devlog.com'

export function setCanonical(path: string): void {
    let link = document.head.querySelector<HTMLLinkElement>('link[rel="canonical"]')
    if (!link) {
        link = document.createElement('link')
        link.rel = 'canonical'
        document.head.appendChild(link)
    }
    link.href = SITE_URL + path
}

export function setPageDescription(description: string): void {
    setMetaTag('name', 'description', description)
    setMetaTag('property', 'og:description', description)
}

function setMetaTag(attribute: 'name' | 'property', key: string, content: string): void {
    let tag = document.head.querySelector<HTMLMetaElement>(`meta[${attribute}="${key}"]`)
    if (!tag) {
        tag = document.createElement('meta')
        tag.setAttribute(attribute, key)
        document.head.appendChild(tag)
    }
    tag.content = content
}
