import hljs, { registerHighlightLanguages } from '@/utils/highlightSetup'

const COPY_ICON = `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
  <path d="M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z"/>
</svg>`

const CHECK_ICON = `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
  <path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z"/>
</svg>`

function normalizeLanguageClass(codeEl: HTMLElement): void {
    const match = codeEl.className.match(/language-(\S+)/)
    if (!match) {
        return
    }
    if (match[1] === 'cs') {
        codeEl.className = codeEl.className.replace('language-cs', 'language-csharp')
    }
}

export function enhanceCodeBlocks(container: HTMLElement): void {
    registerHighlightLanguages()

    container.querySelectorAll('pre code').forEach((node) => {
        const codeEl = node as HTMLElement
        const pre = codeEl.parentElement as HTMLPreElement | null
        if (!pre || pre.classList.contains('code-block-enhanced')) {
            return
        }

        pre.classList.add('code-block-enhanced')
        normalizeLanguageClass(codeEl)
        hljs.highlightElement(codeEl)

        const button = document.createElement('button')
        button.type = 'button'
        button.className = 'code-copy-btn'
        button.setAttribute('aria-label', 'Copy code')
        button.innerHTML = COPY_ICON

        button.addEventListener('click', async () => {
            const text = codeEl.textContent ?? ''
            try {
                await navigator.clipboard.writeText(text)
            } catch {
                return
            }
            button.innerHTML = CHECK_ICON
            button.classList.add('copied')
            window.setTimeout(() => {
                button.innerHTML = COPY_ICON
                button.classList.remove('copied')
            }, 2000)
        })

        pre.appendChild(button)
    })
}
