
import ErrorModel from '@/data/models/ErrorModel'
import { Component, Prop, Vue } from 'vue-property-decorator'

@Component
export default class ErrorContainer extends Vue {
  
  @Prop()
  error!: ErrorModel

  onButtonClicked(): void {
    if (this.error.onButtonClick != null){
      this.error?.onButtonClick()
    }
  }

}
