import Vue from 'vue'
import VueRouter, { RouteConfig } from 'vue-router'
import AboutView from '@/pages/AboutView.vue'
import BlogView from '@/pages/BlogView.vue'
import PostDetailsView from '@/pages/PostDetailsView.vue'
import PageNotFound from '@/components/ErrorContainer.vue'
import ErrorContainer from '@/components/ErrorContainer.vue'
import PostsDetailsModel from '@/data/models/PostDetailsModel'
import ErrorModel from '@/data/models/ErrorModel'

Vue.use(VueRouter)

export const Routes = {
  ROUTE_HOME : '/home',
  ROUTE_BLOG : '/posts',
  ROUTE_POSTS_PAGE: '/posts/pages/:page',
  ROUTE_POST : '/posts/:id',
  ROUTE_PROJECTS : '/projects',
  ROUTE_ABOUT : '/about'
}

export const SITE_TITLE = 'vv-devlog — dev blog'

const routes: Array<RouteConfig> = [
  { path: '/', component: BlogView, meta: { title: SITE_TITLE } },
  { path: Routes.ROUTE_HOME, name: "Home", component: BlogView, meta: { title: SITE_TITLE } },
  { path: Routes.ROUTE_BLOG, name: "Posts", component: BlogView, meta: { title: 'Posts — vv-devlog' } },
  { path: Routes.ROUTE_POSTS_PAGE,name: "Posts",component:BlogView, meta: { title: 'Posts — vv-devlog' } },
  { path: Routes.ROUTE_POST ,name: "Post",component: PostDetailsView },
  //{ path: Routes.ROUTE_PROJECTS, component: ProjectsView },
  { path: Routes.ROUTE_ABOUT, name: "About", component: AboutView, meta: { title: 'About — vv-devlog' } },
  { path: "*", name: "Error", component: ErrorContainer, meta: { title: 'Page not found — vv-devlog' }, props:{error: ErrorModel.pageNotFound()}}
]

const router = new VueRouter({
  mode: 'history',
  //mode: 'history',
  base: process.env.BASE_URL,
  routes
})

export default router
