import { AxiosError } from 'axios'
import PostModel from '@/data/models/PostModel'
import PostsRepository from '@/data/PostsRepository'
import PostsPageModel from '@/data/models/PostsPageModel'
import PostsDetailsModel from '@/data/models/PostDetailsModel'
import { PostFrontmatter } from '@/data/models/PostFrontmatter'
import { renderMarkdown, resolveAssetUrl } from '@/data/MarkdownRenderer'
import { parseFrontmatter } from '@/data/FrontmatterParser'

class PostsService {

    private repository: PostsRepository = new PostsRepository(process.env.VUE_APP_SERVER_BASE_URL)

    public getPosts(page: number): Promise<PostsPageModel> {
        console.log("loading posts page " + page)
        return this.repository.getPostsPage(page).then((result) => this.preparePostPageDates(result))
    }

    public async getPostDetails(id: string): Promise<PostsDetailsModel> {
        try {
            const markdown = await this.repository.getPostMarkdown(id)
            return this.buildFromMarkdown(id, markdown)
        } catch (error) {
            if (this.isNotFound(error)) {
                const post = await this.repository.getPostDetails(id)
                return this.preparePostDetails(this.fixJsonContentImages(post, id))
            }
            throw error
        }
    }

    private perPostAssetsUrl(postId: string): string {
        return `${process.env.VUE_APP_SERVER_BASE_URL}/data/posts/${postId}/`
    }

    public getCoverCandidates(postId: string): string[] {
        const base = this.perPostAssetsUrl(postId)
        return [base + 'cover.png', base + 'cover.jpg']
    }

    private buildFromMarkdown(postId: string, source: string): PostsDetailsModel {
        const { data, content } = parseFrontmatter(source)
        const frontmatter = data as PostFrontmatter
        const postBaseUrl = this.perPostAssetsUrl(postId)

        const post = new PostsDetailsModel()
        post.postId = postId
        post.title = frontmatter.title ?? ''
        post.titleColor = frontmatter.titleColor ?? ''
        post.date = frontmatter.date ?? ''
        post.dateColor = frontmatter.dateColor ?? ''
        post.tags = frontmatter.tags ?? []
        post.intro = frontmatter.intro ?? ''
        post.subtitleColor = frontmatter.subtitleColor ?? ''
        post.prev = frontmatter.prev ?? null
        post.next = frontmatter.next ?? null
        post.content = {
            type: 'markdown',
            data: renderMarkdown(content, postBaseUrl)
        }
        post.cover = frontmatter.cover?.trim() ? resolveAssetUrl(frontmatter.cover.trim(), postBaseUrl) : null
        post.coverShadow = frontmatter.coverShadow ?? false

        return this.preparePostDetails(post)
    }

    private fixJsonContentImages(post: PostsDetailsModel, postId: string): PostsDetailsModel {
        const postPath = this.perPostAssetsUrl(postId)
        post.content.data = post.content.data.replace(/src="([^"]+)"/g, `src="${postPath}$1"`)
        return post
    }

    private isNotFound(error: unknown): boolean {
        return error instanceof AxiosError && error.response?.status === 404
    }

    private preparePostPageDates(postsPage: PostsPageModel): PostsPageModel {
        postsPage.posts.forEach(
            (post: PostModel) => {
                const parts = post.date.split(".");
                console.log(parseInt(parts[2], 10));
                console.log(parseInt(parts[1], 10));
                console.log(parseInt(parts[0], 10));
                const date = new Date(parseInt(parts[2], 10), parseInt(parts[1], 10) - 1, parseInt(parts[0], 10));
                post.dateString = this.formatCompat(date)
            })
        return postsPage
    }

    private preparePostDetails(post: PostsDetailsModel): PostsDetailsModel {
        if (!post.date) {
            return post
        }
        const parts = post.date.split(".");
        const date = new Date(parseInt(parts[2], 10),
            parseInt(parts[1], 10) - 1,
            parseInt(parts[0], 10));
        post.dateString = this.formatCompat(date);
        return post
    }

    public formatCompat(date: Date) {
        const ms = ['January', 'February', 'March', 'April', 'May', 'June', 'July',
            'August', 'September', 'October', 'November', 'December'];
        return date.getDate() + ' ' + ms[date.getMonth()] + ' ' + date.getFullYear();
    }

}

export default PostsService
