

import { Component, Ref, Vue } from 'vue-property-decorator'
import PostsService from '@/data/PostsService'
import PageNotFound from '@/components/ErrorContainer.vue'
import ErrorContainer from '@/components/ErrorContainer.vue'
import PostsDetailsModel from '@/data/models/PostDetailsModel'
import ErrorModel from '@/data/models/ErrorModel'
import {AxiosError} from 'axios'
import { Route } from 'vue-router'
import { nextTick } from 'vue'
import { enhanceCodeBlocks } from '@/utils/CodeBlockEnhancer'
import { setPageDescription } from '@/utils/meta'

Component.registerHooks([
    'beforeRouteUpdate',
]);

@Component({
     components: {
        PageNotFound,
        ErrorContainer,
  },
}

)
export default class PostDetailsView extends Vue{

    @Ref('postContent') readonly postContent!: HTMLElement

    private postsService = new PostsService()

    postId = ''
    postDetails:  PostsDetailsModel = new PostsDetailsModel()
    currentError: ErrorModel|null = null

    get coverStyle(): Record<string, string> | undefined {
        return this.postDetails.cover
            ? { backgroundImage: `url("${this.postDetails.cover}")` }
            : undefined
    }
    

    beforeRouteUpdate(to: Route, from: Route, next: () => void) {
        let postPageName = "Post("+to.params.id+")"
        document.title = postPageName
        to.name = postPageName
        this.postId = to.params.id
        this.getPostDetails()
        next()
    }

    mounted(){
        this.postId= this.$route.params.id
        this.getPostDetails()
    }

    private getPostDetails(){
        this.currentError = null
        this.postsService.getPostDetails(this.postId).then(
            details => {
                document.title = details.title
                if (details.intro) {
                    setPageDescription(details.intro)
                }
                this.postDetails = details
                this.enhanceRenderedContent()
            }
        ).catch(error => {  
            console.log(error)
            if ((error as AxiosError)) {
                const responseCode = error.response?.status ?? 0
                if (responseCode == 404) {
                    this.currentError = ErrorModel.postNotFound()
                } else {
                    this.currentError = ErrorModel.loadPostError(this.getPostDetails)
                }
            }else {
                
                 this.currentError = ErrorModel.loadPostError(this.getPostDetails)
            } 
        })
    }

    private enhanceRenderedContent(): void {
        nextTick(() => {
            if (this.postContent) {
                enhanceCodeBlocks(this.postContent)
            }
        })
    }
}
