<template>
  <div class="consent-banner" v-if="!consentGiven">
    <p>We use cookies to collect and analyse information on site performance and usage</p>
    <md-button class = "md-dense md-raised md-primary consent-button" @click="handleAccept">Accept</md-button>
    <md-button class = "md-dense md-raised md-primary consent-button" @click="handleDeny">Deny</md-button>
  </div>
</template>

<script>


import {setConsent} from "firebase/analytics";

export default {
  name: 'ConsentDialog',
  data() {
    return {
      consentGiven: false,
    };
  },
  methods: {
    handleAccept() {
      // 1. Update Google's Consent Mode

      setConsent({
        analytics_storage: 'granted',
        ad_storage: 'granted'
      })
      localStorage.setItem('user_consent', 'granted');
      this.consentGiven = true;
    },
    handleDeny() {
      setConsent({
        analytics_storage: 'denied',
        ad_storage: 'denied'
      })
      localStorage.setItem('user_consent', 'denied');
      this.consentGiven = true;
    },
  },
  mounted() {
    // Check if user has already made a choice
    if (localStorage.getItem('user_consent')) {
      this.consentGiven = true;
    }
  },
};
</script>

<style scoped>
.consent-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  width: 100%;
  background: #323232;
  color: white;
  padding: 1rem;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 1rem;
  z-index: 1000;
}

