import yaml from 'js-yaml'
import { PostFrontmatter } from '@/data/models/PostFrontmatter'

const FRONTMATTER_PATTERN = /^---\r?\n([\s\S]*?)\r?\n---\r?\n([\s\S]*)$/

export function parseFrontmatter(source: string): { data: PostFrontmatter, content: string } {
    const match = source.match(FRONTMATTER_PATTERN)
    if (!match) {
        return { data: {}, content: source }
    }

    const parsed = yaml.load(match[1])
    const data = (parsed && typeof parsed === 'object' ? parsed : {}) as PostFrontmatter
    return { data, content: match[2] }
}
