import Vue from 'vue'
import router from './router'
import App from './App.vue'
import { initializeApp } from "firebase/app";
import { getAnalytics } from "firebase/analytics";
import { logEvent } from "firebase/analytics";

import VueMaterial from 'vue-material'
import 'vue-material/dist/vue-material.css'
import { setCanonical } from '@/utils/meta'
import { Routes, SITE_TITLE } from '@/router'



Vue.use(VueMaterial)
//Vue.use(hljs.vuePlugin)
Vue.config.productionTip = false

const firebaseConfig = {
  apiKey: "AIzaSyA4d_NC2IzKykTdFJ0BXLnu11PSH3KlLFc",
  authDomain: "vvdevlogsweb.firebaseapp.com",
  projectId: "vvdevlogsweb",
  storageBucket: "vvdevlogsweb.firebasestorage.app",
  messagingSenderId: "936751473313",
  appId: "1:936751473313:web:5d90bcb4f8082aa88906e0",
  measurementId: "G-R1L1G3CKCG"
};

// Initialize Firebase
const app = initializeApp(firebaseConfig);
const analytics = getAnalytics(app);

new Vue({
  router,
  render: h => h(App)
}).$mount('#app')

router.beforeEach( async ( to, from,next ) => {
      document.title = (to.meta && to.meta.title) ? to.meta.title : SITE_TITLE
      setCanonical(to.path === Routes.ROUTE_HOME ? '/' : to.path)
      logEvent(analytics, 'page_view', {
        page_title: to.name??"",
        page_path: to.path
      })
      next()
    });