
class ErrorModel{

    private constructor(
        readonly title: string,
        readonly description: string,
        readonly iconName: string,
        readonly button: string|null,
        readonly onButtonClick: (()=>void)|null
        ){}

        public static pageNotFound(): ErrorModel {
            return new this(
                "Page not found", 
                "The page you requested could not be found",
                "search_off",
                null,null);
        }

        public static loadPageError(retry: ()=>void): ErrorModel {
            return new this(
                "Error loading page",
                "An error has occured",
                "error_outline",
                "Retry",
                retry
            )
        }

        public static postNotFound(): ErrorModel {
            return new this(
                "Post not found", 
                "The post you requested could not be found",
                "search_off",
                null,null);
        }

        public static loadPostError(retry: ()=>void): ErrorModel {
            return new this(
                "Error loading post", 
                "An error occured while loading a post",
                "error_outline",
                "Retry",
                retry);
        }

}

export default ErrorModel